BEGIN;
SELECT no_plan();
UPDATE app.check_in_assignments SET due_date=now()+interval '1 day' WHERE id='c1111111-1111-4111-8111-111111111111';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT set_config('test.before',coalesce((SELECT last_at::text FROM api.daily_patients WHERE id='f1111111-1111-4111-8111-111111111111'),'none'),true);
SELECT lives_ok($$SELECT api.record_daily_weight('f1111111-1111-4111-8111-111111111111',CURRENT_DATE,70,'eeeeeeee-1111-4111-8111-111111111111')$$,'Professional records weight');
SELECT is(coalesce((SELECT last_at::text FROM api.daily_patients WHERE id='f1111111-1111-4111-8111-111111111111'),'none'),current_setting('test.before'),'Professional edit not patient activity');
SELECT throws_ok($$SELECT api.record_daily_weight('f1111111-1111-4111-8111-111111111111',CURRENT_DATE+1,70,gen_random_uuid())$$,NULL,NULL,'Future weight rejected');
SELECT set_config('test.list',api.save_daily_list(NULL,'11111111-1111-4111-8111-111111111111','Tareas',7,'[{"id":"eeeeeeee-2222-4222-8222-222222222222","text":"Caminar"}]',NULL)::text,true);
SELECT lives_ok($$SELECT api.set_daily_list_assignment(current_setting('test.list')::uuid,'f1111111-1111-4111-8111-111111111111',true,false)$$,'Assign list');
SELECT set_config('request.jwt.claims','{"sub":"d1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT lives_ok($$SELECT api.record_daily_weight('f1111111-1111-4111-8111-111111111111',CURRENT_DATE-1,71,'eeeeeeee-3333-4333-8333-333333333333')$$,'Patient backdates weight');
SELECT lives_ok($$SELECT api.record_daily_weight('f1111111-1111-4111-8111-111111111111',CURRENT_DATE-1,71,'eeeeeeee-3333-4333-8333-333333333333')$$,'Retry idempotent');
SELECT is((SELECT count(*) FROM api.daily_weights WHERE id='eeeeeeee-3333-4333-8333-333333333333'),1::bigint,'No duplicate');
SELECT ok((SELECT last_at IS NOT NULL FROM api.daily_patients WHERE id='f1111111-1111-4111-8111-111111111111'),'Patient activity tracked');
SELECT lives_ok($$SELECT api.respond_daily_task(current_setting('test.list')::uuid,'eeeeeeee-2222-4222-8222-222222222222',true,'Hecho')$$,'Patient checks and comments');
SELECT lives_ok($$SELECT api.submit_daily_checkin('c1111111-1111-4111-8111-111111111111',4::smallint,4::smallint,false,'Bien','{}')$$,'Patient answers check-in');
SELECT throws_ok($$SELECT api.submit_daily_checkin('c1111111-1111-4111-8111-111111111111',4::smallint,4::smallint,false,'Otra','{}')$$,NULL,NULL,'Cannot overwrite response');
SELECT set_config('request.jwt.claims','{"sub":"d2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.daily_task_activity WHERE list_id=current_setting('test.list')::uuid),0::bigint,'Other patient cannot read task');
SELECT throws_ok($$SELECT api.respond_daily_task(current_setting('test.list')::uuid,'eeeeeeee-2222-4222-8222-222222222222',false,'Hack')$$,NULL,NULL,'Other patient cannot write task');
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT lives_ok($$SELECT api.set_daily_list_assignment(current_setting('test.list')::uuid,NULL,false,false)$$,'Withdraw list');
SELECT throws_ok($$SELECT api.set_daily_list_assignment(current_setting('test.list')::uuid,'f2222222-2222-4222-8222-222222222222',true,false)$$,NULL,NULL,'Cannot transfer responses to another patient');
SELECT set_config('request.jwt.claims','{"sub":"b3333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.daily_weights WHERE patient_id='f1111111-1111-4111-8111-111111111111'),0::bigint,'Unassigned nutritionist denied');
SELECT set_config('request.jwt.claims','{"sub":"a0000000-0000-4000-8000-000000000000","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.daily_weights),0::bigint,'Admin cannot read clinical weights');
SELECT ok(NOT has_table_privilege('authenticated','app.daily_weights','INSERT'),'Direct DML denied');
SELECT * FROM finish();
ROLLBACK;
